const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const A = input[0];
const B = input[1];

// Contando a partir da cadeira 1 no sentido anti-horário,
// a cadeira final é (número sorteado) % 3.
// Ana senta na cadeira (A % 3).
const ana = A % 3;

// Beatriz mira a cadeira (B % 3); se for a de Ana, senta na próxima
// no sentido anti-horário (cadeiras 0,1,2 numeradas anti-horário,
// logo "próxima" é (c + 1) % 3).
let b = B % 3;
if (b === ana) b = (b + 1) % 3;

// Carolina fica com a cadeira restante (0 + 1 + 2 = 3).
console.log(3 - ana - b);
